export function findLevel(id) {
  return LEVELS.find((l) => l.id === id) ?? null;
}

/** Topic titles and summaries for a level, without loading its content. */
export function topicList(levelId) {
  return CATALOG[levelId] ?? [];
}

/** Title lookup for a progress key such as "g1-5/fractions-add-sub". */
export function describeTopic(key) {
  const [levelId, topicId] = key.split('/');
  const level = findLevel(levelId);
  const meta = topicList(levelId).find((t) => t.id === topicId);
  if (!level || !meta) return null;
  return { level, meta, key };
}

export const topicKey = (levelId, topicId) => `${levelId}/${topicId}`;

const loaded = new Map();

/** Load every topic of a level (cached). Returns the array of topic objects. */
export async function loadLevel(levelId) {
  if (loaded.has(levelId)) return loaded.get(levelId);
  const level = findLevel(levelId);
  if (!level) throw new Error(`Unknown level "${levelId}"`);
  const promise = level.load().then((mod) => mod.default);
  loaded.set(levelId, promise);
  try {
    return await promise;
  } catch (err) {
    loaded.delete(levelId);
    throw err;
  }
}

const topicCache = new Map();

/**
 * Load one topic, or null if it does not exist. Only that topic's file is downloaded (a topic's
 * file name is its id), so opening a lesson does not pull in the whole level.
 */
export async function loadTopic(levelId, topicId) {
  // Only ids listed in the catalogue are ever turned into a file path.
  if (!findLevel(levelId) || !topicList(levelId).some((t) => t.id === topicId)) return null;
  const key = topicKey(levelId, topicId);
  if (!topicCache.has(key)) {
    const promise = import(`./levels/${levelId}/${topicId}.js`).then((mod) => mod.default);
    topicCache.set(key, promise);
    promise.catch(() => topicCache.delete(key));
  }
  return topicCache.get(key);
}
